{"path": "/app/server.py", "content": "from __future__ import annotations

from concurrent import futures
import threading

import grpc

import kv_store_pb2
import kv_store_pb2_grpc


class Server(kv_store_pb2_grpc.KVStoreServicer):
    def __init__(self) -> None:
        self._store: dict[str, int] = {}
        self._lock = threading.Lock()

    def GetVal(self, request: kv_store_pb2.GetValRequest, context: grpc.ServicerContext) -> kv_store_pb2.GetValResponse:
        with self._lock:
            value = int(self._store.get(request.key, 0))
        return kv_store_pb2.GetValResponse(val=value)

    def SetVal(self, request: kv_store_pb2.SetValRequest, context: grpc.ServicerContext) -> kv_store_pb2.SetValResponse:
        with self._lock:
            self._store[request.key] = int(request.val)
        return kv_store_pb2.SetValResponse(val=int(request.val))


def serve() -> None:
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    kv_store_pb2_grpc.add_KVStoreServicer_to_server(Server(), server)
    server.add_insecure_port("[::]:5328")
    server.start()
    server.wait_for_termination()


if __name__ == "__main__":
    serve()
"}

